import * as React from "react";

export type TapeIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TapeIcon({ size = 20, ...props }: TapeIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="10" cy="13" r="6" /><circle cx="10" cy="13" r="2.2" /><path d="M13.5 8.5 L20 5.5 L19 9.5 Z" />
    </svg>
  );
}
